from fastapi import APIRouter, Depends, HTTPException, status
import stripe

router = APIRouter(prefix="/merchants")

@router.get("/{account_id}/charges")
async def list_connected_account_charges(
    account_id: str,
    limit: int = 25,
    user: User = Depends(get_current_user)
):
    if user.stripe_account_id != account_id and not user.is_support_admin:
        raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail="Access denied to merchant charge logs")

    try:
        charges = stripe.Charge.list(
            limit=limit,
            stripe_account=account_id
        )
        return {
            "account_id": account_id,
            "data": [{"id": c.id, "amount": c.amount, "customer": c.billing_details.name, "created": c.created} for c in charges.auto_paging_iter()]
        }
    except stripe.error.StripeError as e:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail=str(e))
